#!/usr/bin/env bash
# Copyright (C) 2026 rezky_nightky
# SPDX-License-Identifier: GPL-3.0-only
# OS: Linux only — zylaxion is a Linux eBPF tool; no other OS is supported.
#
# regenerate-ebpf-prebuilt.sh (night-improve-25) — rebuild the tap
# object and refresh ebpf-prebuilt/ after any change under ebpf/.
#
# The manifest's ebpf_tree_sha256 recipe (documented here so it is
# reproducible from now on — the value committed by night-improve-23
# was generated by an unrecorded command and could not be reproduced
# from history; this script is now the one way the number is made):
#
#   git ls-files ebpf/ | LC_ALL=C sort | xargs sha256sum \
#     | awk '{print $1}' | LC_ALL=C sort | sha256sum
#
# (per-file sha256 content digests of the git-tracked ebpf/ files,
# byte-order sorted, one digest per line, sha256 over the list).
set -euo pipefail
cd "$(dirname "$0")/../.."   # repo root

OBJ=ebpf/target/bpfel-unknown-none/release/zylaxion-tap
[ -f "$OBJ" ] || { echo "no built object at $OBJ — run: cd ebpf && cargo build --release" >&2; exit 1; }

TREE_SHA=$(git ls-files ebpf/ | LC_ALL=C sort | xargs sha256sum | awk '{print $1}' | LC_ALL=C sort | sha256sum | awk '{print $1}')
OBJ_SHA=$(sha256sum "$OBJ" | awk '{print $1}')
OBJ_SIZE=$(stat -c %s "$OBJ")
GENERATED=$(date -u +%Y-%m-%dT%H:%M:%SZ)

install -m 644 "$OBJ" ebpf-prebuilt/zylaxion-tap

cat > ebpf-prebuilt/manifest.toml <<EOF
# Copyright (C) 2026 rezky_nightky
# SPDX-License-Identifier: GPL-3.0-only
#
# zylaxion prebuilt eBPF object manifest (night-improve-23, the
# zelynic NIGHT-ask-2 shape). Generated after the ebpf/ tree build
# — regenerate after any change under ebpf/ so the embedded object
# never drifts from the source (scripts/dev/regenerate-ebpf-prebuilt.sh
# is the generator). ebpf_tree_sha256 pins the exact ebpf/ source tree
# the object was built from: the sha256 over the byte-order-sorted
# (LC_ALL=C) per-file sha256 content digests of the git-tracked ebpf/
# files — one digest per line, list hashed as a whole. These
# are the same bytes the registry-install binaries embed.

schema = 1
generated = "$GENERATED"
toolchain = "nightly-2026-09-18"
bpf_linker = "0.11.1"
ebpf_tree_sha256 = "$TREE_SHA"

[[object]]
name = "zylaxion-tap"
sha256 = "$OBJ_SHA"
size = $OBJ_SIZE
EOF

echo "manifest written:"
cat ebpf-prebuilt/manifest.toml
